def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved.

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']
    """
    # Build a mapping from element to its position in each ordering
    # where it appears
    positions = {}
    for ordering in orderings:
        for i, item in enumerate(ordering):
            if item not in positions:
                positions[item] = []
            positions[item].append((i, ordering))

    # Build precedence constraints: if a appears before b in some ordering,
    # then a must appear before b in the result
    precedence = {}
    for ordering in orderings:
        for i, item in enumerate(ordering):
            if item not in precedence:
                precedence[item] = set()
            for j in range(i + 1, len(ordering)):
                if ordering[j] not in precedence:
                    precedence[ordering[j]] = set()
                precedence[ordering[j]].add(item)

    # Topological sort respecting precedence constraints
    result = []
    remaining = set()
    for ordering in orderings:
        for item in ordering:
            remaining.add(item)

    # Process elements in order of first appearance in orderings
    seen = set()
    for ordering in orderings:
        for item in ordering:
            if item not in seen:
                seen.add(item)

    # Build result by respecting precedence
    result = []
    remaining = set()
    for ordering in orderings:
        for item in ordering:
            remaining.add(item)

    # Use Kahn's algorithm with precedence constraints
    in_degree = {item: 0 for item in remaining}
    graph = {item: [] for item in remaining}
    for item in remaining:
        for ordering in orderings:
            try:
                idx = ordering.index(item)
                for j in range(idx + 1, len(ordering)):
                    if ordering[j] not in graph:
                        graph[ordering[j]] = []
                    graph[item].append(ordering[j])
                    in_degree[ordering[j]] += 1
            except ValueError:
                pass

    # Fix: Recompute in_degree and graph properly
    in_degree = {item: 0 for item in remaining}
    graph = {item: [] for item in remaining}
    for ordering in orderings:
        for i, item in enumerate(ordering):
            for j in range(i + 1, len(ordering)):
                if ordering[j] not in graph[item]:
                    graph[item].append(ordering[j])
                    in_degree[ordering[j]] += 1

    # Kahn's algorithm
    queue = [item for item in remaining if in_degree[item] == 0]
    queue.sort(key=lambda x: orderings[0].index(x) if x in orderings[0] else len(orderings[0]))
    while queue:
        item = queue.pop(0)
        result.append(item)
        for neighbor in graph[item]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)
        queue.sort(key=lambda x: orderings[0].index(x) if x in orderings[0] else len(orderings[0]))

    return result

