def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    if not hasattr(context, "error"):
        context.error = {}

    # Map error fields to x, y, z coordinates if present
    error_fields = [key for key in self._data.keys() if key.startswith("error_")]
    coord_names = ["x", "y", "z"]

    for i, field in enumerate(error_fields[:3]):
        if i < len(coord_names):
            coord_name = coord_names[i]
            # Extract the base name (e.g., error_E_low -> E_low)
            base_name = field[6:]  # Remove "error_" prefix
            if "low" in base_name:
                suffix = "low"
            elif "high" in base_name:
                suffix = "high"
            else:
                suffix = "low"  # default

            error_key = f"{coord_name}_{suffix}"
            # Find index of the error field in the data
            try:
                index = list(self._data.keys()).index(field)
                if error_key not in context.error:
                    context.error[error_key] = {"index": index}
                else:
                    # Append to existing if needed
                    if isinstance(context.error[error_key], dict):
                        context.error[error_key]["index"] = [context.error[error_key]["index"], index]
                    elif isinstance(context.error[error_key], list):
                        context.error[error_key].append(index)
            except ValueError:
                pass  # Field not found in data, skip

