        self.spec_version = spec_version
        self.errors = []
        self.warnings = []
        self.all_versions = {}
        self.unnormalized_digests = {}
        self.manifest_files = []
        self.head = "0"

    def error(self, code, **kwargs):
        self.errors.append((code, kwargs))

    def warning(self, code, **kwargs):
        self.warnings.append((code, kwargs))

    def validate(self, inventory, extract_spec_version=False):
        if 'id' in inventory:
            iid = inventory['id']
            if not isinstance(iid, str):
                self.error('E037a', id=iid)
            elif not re.match(r'[a-z][a-z\d\+\-.]*:.*', iid, re.IGNORECASE):
                self.warning('W005', id=iid)
            else:
                m = re.match(r'https://ocfl.io/(\d+\.\d+)/spec/#inventory', inventory.get('type', ''))
                if m:
                    if m.group(1) != self.spec_version:
                        self.error('E038c', got=m.group(1), assumed_spec_version=self.spec_version)
