def validate_as_prior_version(self, prior):
    if prior.head not in self.all_versions:
        self.error("E066a", prior_head=prior.head)
        return

    prior_versions_set = set(prior.all_versions)
    self_versions_set = set(self.all_versions)
    if not prior_versions_set.issubset(self_versions_set):
        self.error("E066a", prior_head=prior.head)
        return

    for version in prior.all_versions:
        if version == 'no-version':
            self.error("E066a", prior_head=prior.head)
            return

        prior_map = get_logical_path_map(prior.inventory, version)
        self_map = get_logical_path_map(self.inventory, version)

        only_in_prior = prior_map.keys() - self_map.keys()
        only_in_self = self_map.keys() - prior_map.keys()

        if only_in_prior:
            self.error("E066b", version=version, prior_head=prior.head,
                       only_in=prior.head, logical_paths=','.join(only_in_prior))
        if only_in_self:
            self.error("E066b", version=version, prior_head=prior.head,
                       only_in=self.where, logical_paths=','.join(only_in_self))

        for logical_path in prior_map:
            this_map = prior_map[logical_path]
            if logical_path not in self_map:
                continue
            self_map_path = self_map[logical_path]
            if not this_map.issubset(self_map_path):
                self.error("E066c", version=version, prior_head=prior.head,
                           logical_path=logical_path,
                           prior_content=','.join(this_map),
                           current_content=','.join(self_map_path))

        prior_version = prior.inventory['versions'][version]
        self_version = self.inventory['versions'][version]

        for key in prior_version:
            if key not in self_version:
                self.error("E066b", version=version, prior_head=prior.head,
                           only_in=prior.head, logical_paths=key)
                continue

            prior_value = prior_version.get(key)
            self_value = self_version.get(key)
            if prior_value != self_value:
                self.warning("W011", version=version, prior_head=prior.head, key=key)

        for key in self_version:
            if key not in prior_version:
                self.warning("W011", version=version, prior_head=prior.head, key=key)

        prior_state = prior_version.get('state', {})
        self_state = self_version.get('state', {})

        for digest in prior_state:
            if digest not in self_state:
                self.error("E066d", version=version, prior_head=prior.head, digest=digest)
            elif prior_state[digest] != self_state[digest]:
                self.error("E066e", version=version, prior_head=prior.head, digest=digest)

        for digest in self_state:
            if digest not in prior_state:
                self.error("E066d", version=version, prior_head=prior.head, digest=digest)

