def validate_as_prior_version(self, prior):
    if prior.head not in self.all_versions:
        self.error("E066a", prior_head=prior.head)
        return

    if not prior.all_versions.issubset(self.all_versions):
        self.error("E066", prior_versions=','.join(sorted(prior.all_versions - self.all_versions)))

    for version in prior.all_versions:
        if version == 'no-version':
            continue

        prior_map = get_logical_path_map(prior.inventory, version)
        self_map = get_logical_path_map(self.inventory, version)

        only_in_prior = prior_map.keys() - self_map.keys()
        only_in_self = self_map.keys() - prior_map.keys()

        if only_in_prior:
            self.error("E066b", version=version, prior_head=prior.head,
                       only_in=prior.head, logical_paths=','.join(sorted(only_in_prior)))

        if only_in_self:
            self.error("E066b", version=version, prior_head=prior.head,
                       only_in=self.where, logical_paths=','.join(sorted(only_in_self)))

        self.compare_states_for_version(prior, version)

        for logical_path in prior_map:
            this_map = prior_map[logical_path]
            if logical_path not in self_map:
                continue
            if not this_map.issubset(self_map[logical_path]):
                self.error("E066c", version=version, prior_head=prior.head,
                           logical_path=logical_path,
                           prior_content=','.join(sorted(this_map)),
                           current_content=','.join(sorted(self_map[logical_path])))

        prior_version = prior.inventory['versions'][version]
        self_version = self.inventory['versions'][version]

        for key in prior_version:
            if key == 'state':
                continue
            if key not in self_version:
                self.warning("W011", version=version, prior_head=prior.head, key=key)
            elif prior_version.get(key) != self_version.get(key):
                self.warning("W011", version=version, prior_head=prior.head, key=key)

        # Digest validation
        prior_state = prior_version.get('state', {})
        self_state = self_version.get('state', {})

        all_digest_keys = set(prior_state.keys()) | set(self_state.keys())
        for digest_key in all_digest_keys:
            prior_digest = prior_state.get(digest_key, {})
            self_digest = self_state.get(digest_key, {})

            if digest_key not in prior_state:
                self.error("E066d", version=version, prior_head=prior.head,
                           digest_key=digest_key, logical_paths=', '.join(sorted(self_digest.keys())))
            elif digest_key not in self_state:
                self.error("E066e", version=version, prior_head=prior.head,
                           digest_key=digest_key, logical_paths=', '.join(sorted(prior_digest.keys())))
            else:
                for logical_path in prior_digest:
                    if logical_path not in self_digest:
                        self.error("E066d", version=version, prior_head=prior.head,
                                   digest_key=digest_key, logical_paths=', '.join([logical_path]))
                    elif prior_digest[logical_path] != self_digest[logical_path]:
                        self.error("E066c", version=version, prior_head=prior.head,
                                   logical_path=logical_path,
                                   prior_content=prior_digest[logical_path],
                                   current_content=self_digest[logical_path])

