                if m:
                    name = m.group(1)
                    if name in prior_manifest_digests:
                        if prior_manifest_digests[name] != digest_file:
                            self.log.error('E023b', where=version_dir, missing_filepaths=name)
                    else:
                        prior_manifest_digests[name] = digest_file
                else:
                    self.log.error('E023b', where=version_dir, missing_filepaths=digest_file)

            for digest_file in inv_validator.fixity_files:
                m = re.match('(\\w+)\\s+(\\S+)\\s*$', digest_file)
                if m:
                    name = m.group(1)
                    if name in prior_fixity_digests:
                        if prior_fixity_digests[name] != digest_file:
