                else:
                    self.log.error('E023b', where=version_dir, missing_filepaths=digest_file)

            prev_version_dir = version_dir
            prev_spec_version = this_spec_version

        except Exception as e:
            self.log.error('E023b', where=version_dir, missing_filepaths=str(e))

