    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    flags = []

    # Extract flags from regular actions (including --long, -short options)
    for action in parser._actions:
        if action.option_strings:
            flags.extend(action.option_strings)
        elif action.dest != 'help':
            # Positional arguments have no option_strings, use dest as identifier
            flags.append(action.dest)

    # Handle subparsers if they exist
    if hasattr(parser, '_subparsers') and parser._subparsers:
        for action in parser._subparsers._actions:
            if hasattr(action, 'choices') and action.choices:
                for choice in action.choices:
                    flags.append(choice)

    return ' '.join(flags)

