def size_to_bytes(size: str) -> int:
    if size is None:
        return 0
    units = {
        'K': 1000,
        'M': 1000000,
        'G': 1000000000,
        'T': 1000000000000,
        'P': 1000000000000000
    }
    size = str(size).strip()
    if not size:
        return 0
    if size[-1].isdigit():
        return int(float(size))
    suffix = size[-1].upper()
    if suffix in units:
        return int(float(size[:-1]) * units[suffix])
    return int(float(size))

