            [^\s"']+                              # unquoted token
        )'''
    elif platform == 0:
        # Windows/CMD mode
        pattern = r'''(
            \s+|                                    # whitespace
            "[^"\\]*(?:\\.[^"\\]*)*"|              # double-quoted string
            [^\s"]+                                # unquoted token
        )'''
    else:
        raise ValueError(f"Unsupported platform value: {platform}")

    result = []
    for match in re.finditer(pattern, s, re.VERBOSE):
        token = match.group(0).strip()
        if token:
            if (token[0] == '"' and token[-1] == '"') or (token[0] == "'" and token[-1] == "'"):
