def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = collections.OrderedDict()
    logs = []

    for config_filename in config_filenames:
        try:
            config = validate.parse_configuration(config_filename, validate.schema_filename(), overrides, resolve_env)
            configs[config_filename] = config
        except PermissionError:
            logs.extend([
                logging.makeLogRecord(dict(levelno=logging.WARNING, levelname='WARNING', msg='{}: Insufficient permissions to read configuration file'.format(config_filename)))
            ])
        except Exception as error:
            logs.extend([
                logging.makeLogRecord(dict(levelno=logging.CRITICAL, levelname='CRITICAL', msg='{}: Error parsing configuration file'.format(config_filename))),
                logging.makeLogRecord(dict(levelno=logging.CRITICAL, levelname='CRITICAL', msg=error))
            ])

    return (configs, logs)

