        seq = fill_compute_seq.FillComputeSeq(*seq)
        seq_type = "fill_compute"
    elif ct.is_fill_request_el(seq):
        seq = fill_request_seq.FillRequestSeq(
            *seq, bufsize=bufsize,
            # if we have a FillRequest element inside,
            # it decides itself when to reset.
            reset=False,
