def scale(self, other=None, recompute=False):
    if other is None:
        if self._scale is None or recompute:
            unified_bins, unified_edges = hf.unify_1_md(self.bins, self.edges)
            self._scale = hf.integral(*hf.unify_1_md(self.bins, self.edges))
        return self._scale
    else:
        scale = self.scale()
        if scale == 0:
            raise lena.core.LenaValueError(
                "can not rescale histogram with zero scale"
            )
        self.bins = lena.math.md_map(lambda binc: binc * float(other) / scale, self.bins)
        self._scale = float(other)
        return None

