def scale(self, other=None):
    if other is None:
        if self._scale is None or self._scale == 0:
            raise LenaValueError("Cannot get scale of graph with unknown or zero scale")
        return self._scale
    else:
        if other == 0:
            raise LenaValueError("Cannot rescale to zero")
        if self._scale is None:
            raise LenaValueError("Cannot rescale graph with unknown scale")
        self._scale = other
        idx = -1
        if len(self._data) > 0:
            self._data[idx] *= other
        if hasattr(self, "_errors") and self._errors is not None:
            for i, err in enumerate(self._errors):
                if i == idx:
                    self._errors[i] *= other
        return self

