def validate_arg_deprecation(cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    deprecated_args = []

    # Check for deprecated arguments in cli_args
    if cli_args:
        for key in cli_args:
            if key.startswith('deprecated_'):
                deprecated_args.append((key, cli_args[key]))

    # Check for deprecated arguments in answer_file_args
    if answer_file_args:
        for key in answer_file_args:
            if key.startswith('deprecated_'):
                deprecated_args.append((key, answer_file_args[key]))

    # Print deprecated arguments if any found
    if deprecated_args:
        print("Deprecated arguments detected:")
        for arg_name, arg_value in deprecated_args:
            print(f"  {arg_name}: {arg_value}")
    else:
        print("No deprecated arguments found.")

