import java.util.*;

public class CompleteBipartiteGraphGenerator {
    /**
     * Construct a complete bipartite graph
     */
    public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
        if (resultMap == null) {
            throw new IllegalArgumentException("resultMap cannot be null");
        }

        // Define partitions
        List<V> partitionA = new ArrayList<>();
        List<V> partitionB = new ArrayList<>();

        // Add vertices to partition A
        for (int i = 0; i < 5; i++) {
            V vertex = (V) new Object();
            if (target.addVertex(vertex)) {
                partitionA.add(vertex);
                resultMap.put("A" + i, vertex);
            }
        }

        // Add vertices to partition B
        for (int i = 0; i < 5; i++) {
            V vertex = (V) new Object();
            if (target.addVertex(vertex)) {
                partitionB.add(vertex);
                resultMap.put("B" + i, vertex);
            }
        }

        // Add edges between all pairs from partition A and partition B
        for (V u : partitionA) {
            for (V v : partitionB) {
                if (target.containsVertex(u) && target.containsVertex(v)) {
                    target.addEdge(u, v);
                }
            }
        }
    }
}

