public class CompleteBipartiteGraphGenerator<V, E> {
    /**
     * Construct a complete bipartite graph
     */
    public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
        // Create two disjoint sets of vertices: U and V
        // For a complete bipartite graph K_{m,n}, we create m vertices in set U and n vertices in set V
        // Here we assume m=3 and n=3 for demonstration, but can be generalized

        // Add vertices to set U
        V u1 = (V)"U1";
        V u2 = (V)"U2";
        V u3 = (V)"U3";
        target.addVertex(u1);
