        V v1 = (V)"V1";
        V v2 = (V)"V2";
        V v3 = (V)"V3";
        target.addVertex(v1);
        target.addVertex(v2);
        target.addVertex(v3);

        // Store vertices in resultMap for reference
        resultMap.put("U1", u1);
        resultMap.put("U2", u2);
        resultMap.put("U3", u3);
        resultMap.put("V1", v1);
        resultMap.put("V2", v2);
        resultMap.put("V3", v3);

        // Add all possible edges between U and V (complete bipartite)
        target.addEdge(u1, v1);
        target.addEdge(u1, v2);
        target.addEdge(u1, v3);
        target.addEdge(u2, v1);
