public boolean equals(final Object o)
{
    if (o instanceof ByteString) {
        ByteString other = (ByteString) o;
        if (this == other) {
            return true;
        }
        if (this.bytes.length != other.bytes.length) {
            return false;
        }
        for (int i = 0; i < this.bytes.length; i++) {
            if (this.bytes[i] != other.bytes[i]) {
                return false;
            }
        }
        return true;
    }
    return false;
}

