public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        return new LinkedList<>();
    }
    String rawPath = u.getRawPath();
    if (rawPath == null) {
        return new LinkedList<>();
    }
    if (rawPath.length() == 0) {
        return new LinkedList<>();
    }
    if (rawPath.charAt(0) == '/') {
        rawPath = rawPath.substring(1);
    }
    return decodePath(rawPath, decode);
}

public static List<PathSegmentImpl> decodePath(String path, boolean decode) {
    List<PathSegmentImpl> segments = new LinkedList<>();
    if (path == null || path.length() == 0) {
        return segments;
    }
    int e = -1;
    int s = 0;
    while ((e = path.indexOf('/', s)) != -1) {
        segments.add(decodePathSegment(path.substring(s, e), decode));
        s = e + 1;
    }
    if (s <= path.length()) {
        segments.add(decodePathSegment(path.substring(s), decode));
    }
    return segments;
}

