     * @param o1 the first value
     * @param o2 the second value
     * @return 0 if they are equal, -1 if {@literal o1 < o2}, 1 otherwise
     */
    public int compare(Double o1, Double o2) {
        if (Math.abs(o1 - o2) < epsilon) {
            return 0;
        }
        return Double.compare(o1, o2);
    }
}

