        this.writer = writer;
        this.encoding = encoding;
        this.buf = new byte[8192];
    }

    public WriterOutputStream(final Writer writer, final String encoding) {
        this(writer, Charset.forName(encoding));
    }

    @Override
    public void write(final int b) throws IOException {
