            throw new IOException("Stream closed");
        }
        if (this.buf.length == 0) {
            this.buf = new byte[1];
        } else if (this.buf.length == 1) {
            this.buf = new byte[this.buf.length * 2];
        }
        this.buf[0] = (byte) b;
        this.write(this.buf, 0, 1);
