public void abbreviate(final int nameStart, final StringBuffer buf) {
    int end = buf.length() - 1;
    String bufString = buf.toString();
    int dotIndex = bufString.lastIndexOf(".", end - 1);
    if (dotIndex >= nameStart) {
        buf.delete(nameStart, dotIndex + 1);
    }
    int pos = nameStart;
    while (pos < buf.length()) {
        int nextDot = buf.toString().indexOf(".", pos);
        if (nextDot == -1) break;
        int charCount = nextDot - pos;
        if (charCount > 1) {
            buf.delete(pos + 1, nextDot);
            buf.insert(pos + 1, ".");
            pos = nextDot + 1;
        } else {
            pos = nextDot + 1;
        }
    }
    if (buf.length() > nameStart && buf.charAt(nameStart) == '.') {
        buf.delete(nameStart, nameStart + 1);
    }
}

