public void abbreviate(final int nameStart, final StringBuffer buf) {
        int end = buf.length() - 1;
        String bufString = buf.toString();
        int lastDot = bufString.lastIndexOf(".", end - 1);
        if (lastDot >= nameStart) {
            buf.delete(nameStart, end + 1);
            return;
        }
        int pos = nameStart;
        while (pos < end) {
            int nextDot = bufString.indexOf(".", pos + 1);
            if (nextDot < 0) break;
            buf.delete(nameStart, nextDot + 1);
            bufString = buf.toString();
            end = buf.length() - 1;
            pos = nameStart;
        }
        int startPos = nameStart;
        while (startPos < end) {
            int nextDot = buf.toString().indexOf(".", startPos);
            if (nextDot < 0) break;
            int charCount = nextDot - startPos;
            buf.delete(startPos + charCount, nextDot);
            String ellipsis = "...";
            buf.insert(nextDot, ellipsis);
            startPos = nextDot + ellipsis.length();
            end = buf.length() - 1;
        }
    }

